# Solution 1: Brute Force
# Time Complexity: O(n*m*capacity)
# Space Complexity: O(1)
def brute_force(grid, capacity):
    count = 0
    for well in grid:
        total_water = sum(well)
        if total_water == 0:
            continue
        count += math.ceil(total_water / capacity)
    return count

# Solution 2: Binary Search
# Time Complexity: O(n*log(m))
# Space Complexity: O(1)
def binary_search(grid, capacity):
    low, high = 0, sum(sum(row) for row in grid)
    while low < high:
        mid = (low + high) // 2
        if can_fill(grid, mid, capacity):
            high = mid
        else:
            low = mid + 1
    return low

def can_fill(grid, target, capacity):
    for well in grid:
        total_water = sum(well)
        if total_water > target:
            return False
    return True

return brute_force(grid, capacity)

