def rearange_string(s):
  char_count = Counter(s)
  max_char = max(char_count.values())
  max_chars = [char for char, count in char_count.items() if count == max_char]
  if len(max_chars) > 1 or max_char > len(s)/2:
    return ''
  else:
    s = ''.join(sorted(s))
    return s[:max_char] + ''.join(max_chars) + s[max_char:]

