  dp = [[0]*n for _ in range(n)]
  for i in range(n):
    dp[i][i] = 1
  for l in range(2,n+1):
    for i in range(n-l+1):
      j = i+l-1
      if arr[i]-arr[j]==1 or arr[i]-arr[j]==-1:
        dp[i][j] = dp[i+1][j-1]+1
